    heap=mmap(NULL,sizeof(*heap),PROT_READ|PROT_WRITE,MAP_PRIVATE|MAP_ANONYMOUS,-1,0);
    if (heap==MAP_FAILED) recon_unsupported("private HeapCreate allocation failure");
